8?SwbvBYQl0ssI200dcD"""
assets = json.loads(lzma.decompress(base64.b85decode("".join(PAYLOAD.split()))))
with tempfile.TemporaryDirectory(prefix="ALS_important_plots_") as temporary:
    helperdir = Path(temporary)
    for name, source in assets.items():
        if Path(name).name != name:
            raise ValueError("Invalid embedded helper name")
        (helperdir/name).write_text(source)
    result = subprocess.run([sys.executable, "-u", str(helperdir/"plot_important_snps.py"), *sys.argv[1:]])
    status = result.returncode
sys.exit(status)
